#!/usr/bin/env pwsh
#Requires -Version 7.4
<#
.SYNOPSIS
Removes agent attribution lines from unpushed commits on the current branch.

.DESCRIPTION
Finds commits reachable from the current branch but from no remote-tracking branch or tag, removes
message lines that match -LinePattern, and recreates those commits and their unpushed descendants
with git commit-tree. Trees, parents outside the range, merge topology, author and committer
identities and timestamps are preserved, so the branch tip keeps its tree and the index, working
tree and untracked files are untouched.

The original tip is kept at refs/attribution-backup/<branch>/<unix-time>, and the branch ref is
updated only if it still points at the tip that was inspected. The script never pushes, never
rewrites a commit already on a remote or in a tag, and refuses the default branch, a detached HEAD,
an operation in progress and commits carrying signatures or a custom encoding.

.PARAMETER RepoRoot
Path of the repository whose current branch is cleaned.

.PARAMETER LinePattern
Case-insensitive regular expressions; a message line matching any of them is removed. The default
removes every Co-authored-by trailer and "Generated by/with" agent lines.

.PARAMETER SkipFetch
Skips fetching every remote first. Use only when the remote-tracking refs are known to be current.

.EXAMPLE
./Remove-CommitAttribution.ps1 -RepoRoot ~/source/example -WhatIf

Reports the unpushed commits that would be rewritten and how many lines each would lose.

.EXAMPLE
./Remove-CommitAttribution.ps1 -RepoRoot ~/source/example

Rewrites the unpushed commits and returns a summary including the backup ref.

.NOTES
Requires git. Restore the original history with
git update-ref refs/heads/<branch> <backup-ref> before anything else is committed.
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory = $true)]
    [string]$RepoRoot,

    [Parameter(Mandatory = $false)]
    [string[]]$LinePattern = @(
        '^\s*co-authored-by:',
        '^\s*generated (by|with) .*\b(copilot|claude|codex|chatgpt|gemini|cursor)\b'
    ),

    [Parameter(Mandatory = $false)]
    [switch]$SkipFetch
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 3.0

#region Git

function Invoke-GitText {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Repository,

        [Parameter(Mandatory = $true)]
        [string[]]$Arguments,

        [Parameter(Mandatory = $false)]
        [string]$InputText,

        [Parameter(Mandatory = $false)]
        [hashtable]$Environment,

        [Parameter(Mandatory = $false)]
        [switch]$AllowFailure
    )

    $Git = Get-Command -Name git -CommandType Application -TotalCount 1
    $Utf8 = [Text.UTF8Encoding]::new($false)
    $StartInfo = [Diagnostics.ProcessStartInfo]::new($Git.Source)
    $StartInfo.ArgumentList.Add('-C')
    $StartInfo.ArgumentList.Add($Repository)
    foreach ($Argument in $Arguments) {
        $StartInfo.ArgumentList.Add($Argument)
    }
    $StartInfo.UseShellExecute = $false
    $StartInfo.RedirectStandardInput = $true
    $StartInfo.RedirectStandardOutput = $true
    $StartInfo.RedirectStandardError = $true
    $StartInfo.StandardInputEncoding = $Utf8
    $StartInfo.StandardOutputEncoding = $Utf8
    $StartInfo.StandardErrorEncoding = $Utf8
    if ($Environment) {
        foreach ($Key in $Environment.Keys) {
            $StartInfo.Environment[$Key] = [string]$Environment[$Key]
        }
    }

    $Process = [Diagnostics.Process]::Start($StartInfo)
    if ($InputText) {
        $Process.StandardInput.Write($InputText)
    }
    $Process.StandardInput.Close()
    $OutputTask = $Process.StandardOutput.ReadToEndAsync()
    $ErrorText = $Process.StandardError.ReadToEnd()
    $Output = $OutputTask.GetAwaiter().GetResult()
    $Process.WaitForExit()

    if ($Process.ExitCode -ne 0) {
        if ($AllowFailure) {
            return $null
        }
        throw "git $($Arguments -join ' ') failed with exit code $($Process.ExitCode): $($ErrorText.Trim())"
    }
    return $Output
}

#endregion

#region Commits

function Remove-AttributionLine {
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Message,

        [Parameter(Mandatory = $true)]
        [string[]]$LinePattern
    )

    $Options = [Text.RegularExpressions.RegexOptions]::IgnoreCase
    $Kept = [Collections.Generic.List[string]]::new()
    $Removed = 0
    foreach ($Line in ($Message -split "`n")) {
        $Matched = $false
        foreach ($Pattern in $LinePattern) {
            if ([regex]::IsMatch($Line, $Pattern, $Options)) {
                $Matched = $true
                break
            }
        }
        if ($Matched) {
            $Removed++
        }
        else {
            $Kept.Add($Line)
        }
    }

    if ($Removed -eq 0) {
        return [pscustomobject]@{ Message = $Message; Removed = 0 }
    }
    $Cleaned = ($Kept -join "`n").TrimEnd()
    return [pscustomobject]@{ Message = "$Cleaned`n"; Removed = $Removed }
}

function Get-CommitRecord {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Repository,

        [Parameter(Mandatory = $true)]
        [string]$Sha
    )

    $Raw = Invoke-GitText -Repository $Repository -Arguments @('cat-file', 'commit', $Sha)
    $Separator = $Raw.IndexOf("`n`n")
    $HeaderText = if ($Separator -ge 0) { $Raw.Substring(0, $Separator) } else { $Raw.TrimEnd("`n") }
    $Message = if ($Separator -ge 0) { $Raw.Substring($Separator + 2) } else { '' }

    $Tree = $null
    $Parents = [Collections.Generic.List[string]]::new()
    $Identity = @{}
    foreach ($Line in ($HeaderText -split "`n")) {
        if ($Line.StartsWith(' ')) {
            continue
        }
        $Key, $Value = $Line -split ' ', 2
        switch ($Key) {
            'tree' { $Tree = $Value }
            'parent' { $Parents.Add($Value) }
            { $_ -in 'author', 'committer' } {
                $Match = [regex]::Match($Value, '^(?<name>.*) <(?<email>[^>]*)> (?<date>\d+ [+-]\d{4})$')
                if (-not $Match.Success) {
                    throw "Commit $Sha has an unparseable $Key header."
                }
                $Identity[$Key] = $Match
            }
            { $_ -in 'gpgsig', 'gpgsig-sha256', 'mergetag', 'encoding' } {
                throw "Commit $Sha carries a '$Key' header that a rewrite cannot preserve; clean it manually."
            }
        }
    }

    return [pscustomobject]@{
        Sha      = $Sha
        Tree     = $Tree
        Parents  = @($Parents)
        Author   = $Identity['author']
        Committer = $Identity['committer']
        Message  = $Message
    }
}

function Assert-RewritableBranch {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Repository
    )

    $Branch = Invoke-GitText -Repository $Repository -Arguments @('symbolic-ref', '--quiet', '--short', 'HEAD') -AllowFailure
    if (-not $Branch) {
        throw 'HEAD is detached; check out the branch to clean first.'
    }
    $Branch = $Branch.Trim()

    foreach ($Marker in 'rebase-merge', 'rebase-apply', 'MERGE_HEAD', 'CHERRY_PICK_HEAD', 'REVERT_HEAD') {
        $MarkerPath = (Invoke-GitText -Repository $Repository -Arguments @('rev-parse', '--git-path', $Marker)).Trim()
        if (-not [IO.Path]::IsPathRooted($MarkerPath)) {
            $MarkerPath = Join-Path $Repository $MarkerPath
        }
        if (Test-Path -LiteralPath $MarkerPath) {
            throw "A git operation is in progress ($Marker); finish or abort it first."
        }
    }

    $Remotes = @((Invoke-GitText -Repository $Repository -Arguments @('remote')) -split "`n" | Where-Object { $_ })
    if ($Remotes.Count -eq 0) {
        throw 'The repository has no remote, so published commits cannot be distinguished from unpushed ones.'
    }

    foreach ($Remote in $Remotes) {
        $DefaultRef = Invoke-GitText -Repository $Repository -Arguments @('symbolic-ref', '--quiet', '--short', "refs/remotes/$Remote/HEAD") -AllowFailure
        if ($DefaultRef -and $DefaultRef.Trim() -eq "$Remote/$Branch") {
            throw "Branch '$Branch' is the default branch of '$Remote'; never rewrite it."
        }
    }

    return $Branch
}

#endregion

function Invoke-CommitAttributionRemoval {
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory = $true)]
        [string]$RepoRoot,

        [Parameter(Mandatory = $true)]
        [string[]]$LinePattern,

        [Parameter(Mandatory = $false)]
        [switch]$SkipFetch
    )

    $Repository = (Resolve-Path -LiteralPath $RepoRoot).Path
    $Branch = Assert-RewritableBranch -Repository $Repository
    if (-not $SkipFetch) {
        Invoke-GitText -Repository $Repository -Arguments @('fetch', '--all', '--prune', '--quiet') | Out-Null
    }

    $Tip = (Invoke-GitText -Repository $Repository -Arguments @('rev-parse', 'HEAD')).Trim()
    $Candidates = @((Invoke-GitText -Repository $Repository -Arguments @(
                'rev-list', '--reverse', '--topo-order', 'HEAD', '--not', '--remotes', '--tags'
            )) -split "`n" | Where-Object { $_ })

    $Plan = [Collections.Generic.List[object]]::new()
    $RemovedLines = 0
    foreach ($Sha in $Candidates) {
        $Record = Get-CommitRecord -Repository $Repository -Sha $Sha
        $Cleaned = Remove-AttributionLine -Message $Record.Message -LinePattern $LinePattern
        $RemovedLines += $Cleaned.Removed
        $Plan.Add([pscustomobject]@{ Record = $Record; Message = $Cleaned.Message; Removed = $Cleaned.Removed })
    }

    $Result = [pscustomobject]@{
        Repository       = $Repository
        Branch           = $Branch
        UnpushedCommits  = $Candidates.Count
        RewrittenCommits = 0
        RemovedLines     = $RemovedLines
        OriginalTip      = $Tip
        NewTip           = $Tip
        BackupRef        = $null
    }
    if ($RemovedLines -eq 0) {
        Write-Verbose "No attribution lines in $($Candidates.Count) unpushed commit(s) on '$Branch'."
        return $Result
    }

    $Target = "$($Plan.Where({ $_.Removed -gt 0 }).Count) of $($Candidates.Count) unpushed commit(s) on '$Branch'"
    if (-not $PSCmdlet.ShouldProcess($Target, "Remove $RemovedLines attribution line(s)")) {
        return $Result
    }

    $Map = @{}
    foreach ($Item in $Plan) {
        $Record = $Item.Record
        $Parents = @($Record.Parents | ForEach-Object { if ($Map.ContainsKey($_)) { $Map[$_] } else { $_ } })
        $ParentsChanged = (@($Record.Parents) -join ' ') -ne ($Parents -join ' ')
        if ($Item.Removed -eq 0 -and -not $ParentsChanged) {
            $Map[$Record.Sha] = $Record.Sha
            continue
        }

        $Arguments = @('commit-tree', '--no-gpg-sign', $Record.Tree)
        foreach ($Parent in $Parents) {
            $Arguments += @('-p', $Parent)
        }
        $Environment = @{
            GIT_AUTHOR_NAME     = $Record.Author.Groups['name'].Value
            GIT_AUTHOR_EMAIL    = $Record.Author.Groups['email'].Value
            GIT_AUTHOR_DATE     = $Record.Author.Groups['date'].Value
            GIT_COMMITTER_NAME  = $Record.Committer.Groups['name'].Value
            GIT_COMMITTER_EMAIL = $Record.Committer.Groups['email'].Value
            GIT_COMMITTER_DATE  = $Record.Committer.Groups['date'].Value
        }
        $NewSha = (Invoke-GitText -Repository $Repository -Arguments $Arguments -InputText $Item.Message -Environment $Environment).Trim()
        $Map[$Record.Sha] = $NewSha
        $Result.RewrittenCommits++
    }

    $NewTip = $Map[$Tip]
    foreach ($Item in $Plan) {
        $Rewritten = Get-CommitRecord -Repository $Repository -Sha $Map[$Item.Record.Sha]
        $Check = Remove-AttributionLine -Message $Rewritten.Message -LinePattern $LinePattern
        if ($Rewritten.Tree -ne $Item.Record.Tree -or $Check.Removed -ne 0 -or
            $Rewritten.Author.Value -ne $Item.Record.Author.Value -or
            $Rewritten.Committer.Value -ne $Item.Record.Committer.Value) {
            throw "Verification failed for $($Item.Record.Sha); the branch was not updated."
        }
    }

    $BackupRef = "refs/attribution-backup/$Branch/$([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())"
    Invoke-GitText -Repository $Repository -Arguments @('update-ref', $BackupRef, $Tip) | Out-Null
    Invoke-GitText -Repository $Repository -Arguments @(
        'update-ref', '-m', 'remove commit attribution', "refs/heads/$Branch", $NewTip, $Tip
    ) | Out-Null

    $Result.NewTip = $NewTip
    $Result.BackupRef = $BackupRef
    return $Result
}

if ($MyInvocation.InvocationName -ne '.') {
    try {
        Invoke-CommitAttributionRemoval -RepoRoot $RepoRoot -LinePattern $LinePattern -SkipFetch:$SkipFetch
        exit 0
    }
    catch {
        Write-Error -ErrorAction Continue $_
        exit 1
    }
}
